window.__BUNDLE = {"body": "<div class=\"wrap\">\n\n  <section id=\"intro\" class=\"stack\" style=\"gap:28px\">\n    <div data-greeting></div>\n    <div id=\"testStart\" class=\"stack\" style=\"gap:28px\" hidden>\n      <div class=\"stack\">\n        <div class=\"eyebrow\">Самотест для себе · 10 хвилин</div>\n        <h1>Компас адаптації</h1>\n        <p class=\"lead\">Переїзд до нової країни змінює все: мову, побут, роботу, коло спілкування і навіть те, як ти бачиш себе. Цей тест допоможе зрозуміти, де ти зараз на шляху адаптації, що вже стало опорою і куди зробити наступний крок.</p>\n      </div>\n      <div class=\"roles k-roles\">\n        <div class=\"role ka0\"><b>Мова</b><span>і спілкування</span></div>\n        <div class=\"role ka1\"><b>Побут</b><span>і система</span></div>\n        <div class=\"role ka2\"><b>Справа</b><span>і реалізація</span></div>\n        <div class=\"role ka3\"><b>Люди</b><span>і зв’язки</span></div>\n        <div class=\"role ka4\"><b>Ресурс</b><span>тіло і відпочинок</span></div>\n        <div class=\"role ka5\"><b>Я</b><span>і сенс</span></div>\n      </div>\n      <div class=\"card stack\">\n        <h3>Як це влаштовано</h3>\n        <p>Тут майже немає питань про почуття, лише про те, що ти робиш. Згадай останні 4 тижні й відзначай, як часто це було насправді. Правильних відповідей немає, є лише твоя картина зараз.</p>\n        <p>Спочатку два короткі питання про твій переїзд, потім шість сфер нового життя і невеликий блок про дві культури: твою і нову. Наприкінці ти отримаєш докладний розбір з ілюстраціями, рекомендаціями та питаннями для роздумів. Розбір можна отримати в PDF.</p>\n        <div class=\"scale-legend\"><span><b>0</b> жодного разу</span><span><b>1</b> 1–2 рази</span><span><b>2</b> час від часу</span><span><b>3</b> часто</span><span><b>4</b> майже завжди</span></div>\n      </div>\n      <div data-testinfo></div>\n      <div class=\"stack\">\n        <h3>Як тебе звати?</h3>\n        <div class=\"row\" style=\"align-items:stretch\">\n          <div class=\"field\"><label for=\"nameMe\">Твоє ім’я</label><input id=\"nameMe\" maxlength=\"30\" autocomplete=\"given-name\" placeholder=\"Наприклад, Анна\"></div>\n        </div>\n        <p class=\"note\">Ім’я потрібне лише для гарного розбору.</p>\n      </div>\n      <div><button class=\"btn\" id=\"startBtn\">Почати тест</button></div>\n      <div data-share=\"compact\" style=\"margin-top:8px\"></div>\n    </div>\n  </section>\n\n  <section id=\"quiz\" class=\"stack\" hidden style=\"gap:20px\">\n    <div class=\"stack\" style=\"gap:10px\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <span class=\"eyebrow\" id=\"stepLabel\"></span>\n        <span class=\"eyebrow\" id=\"countLabel\"></span>\n      </div>\n      <div class=\"progress\"><i id=\"prog\" style=\"width:0\"></i></div>\n    </div>\n    <div class=\"stack\" style=\"gap:6px\">\n      <div><span class=\"part-tag\" id=\"partTag\"></span></div>\n      <h2 id=\"roleTitle\"></h2>\n      <p class=\"muted\" id=\"roleSub\"></p>\n    </div>\n    <div class=\"card\" id=\"qlist\" style=\"padding-block:6px\"></div>\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button class=\"btn ghost\" id=\"back\">Назад</button>\n      <button class=\"btn\" id=\"next\" disabled>Далі</button>\n    </div>\n  </section>\n\n  <section id=\"result\" hidden>\n    <div class=\"rep\" id=\"report\"></div>\n    <div data-share style=\"margin-top:18px\"></div>\n    <div data-lead></div>\n  </section>\n\n  <div data-disclaimer style=\"margin-top:28px\"></div>\n</div>\n<div class=\"pdf-stage\" id=\"stage\" aria-hidden=\"true\"></div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = '';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = 'https://irynawiederkehr-cmd.github.io/tests/';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {\n  'roza-lyubvi': 'https://claude.ai/artifact/6Nv7pCtqpAd9xoWUkvEwS1',\n  'kompas': 'https://claude.ai/artifact/5TPCgkiVSZEr8H2g8d1UkY'\n};\n", "const BRAND = 'coach';\nconst TEST_META = { id: 'kompas', name: 'Компас адаптації' };\nconst TEST_INFO = {\n  why: 'Я розробила цей опитувальник, щоб допомогти тобі дбайливо подивитися на своє життя в новій країні. В еміграції легко бачити лише те, що поки не виходить. Опитувальник показує і труднощі, і опори, які в тебе вже є, і допомагає обрати наступний крок, а не намагатися змінити все одразу.',\n  gives: [\n    'Ти побачиш, які з шести сфер нового життя вже стали опорою, а які поки звучать тихо.',\n    'Зрозумієш, як ти зараз тримаєш зв’язок зі своєю культурою і з новою.',\n    'Дізнаєшся, на якому етапі адаптації перебуваєш і що на ньому особливо допомагає.',\n    'Отримаєш план маленьких кроків на 4 тижні та питання для роздумів.'\n  ],\n  next: [\n    'Постався до результату дбайливо: це знімок останніх 4 тижнів, а не оцінка тебе.',\n    'Почни з однієї сфери й одного маленького кроку, а не з усього одразу.',\n    'Спирайся на те, що вже працює: сильні сфери допомагають підтягнути решту.',\n    'Через 4 тижні пройди тест знову й подивися, що змінилося.',\n    'Якщо стає дуже важко, поговори з близькою людиною або з фахівцем.'\n  ]\n};\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Ірина Вознесенська',\n  about: 'Коуч ICF у Швейцарії та психолог в Україні.',\n  coach: { place: 'Швейцарія · Цюрих', title: 'Коуч', text: 'Трансформаційний коуч і нейрокоуч, ICF. Допомагаю російськомовним емігрантам пройти адаптацію: знайти себе і своє місце в новому світі. У Швейцарії працюю лише як коуч. Коучинг не є психотерапією і не замінює психологічної чи медичної допомоги.',\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Україна · Київ', title: 'Психолог в Україні', text: 'Працюю зі стосунками в парі: допомагаю парам почути одне одного, повернути близькість і знайти баланс. Як психолог працюю лише з клієнтами в Україні, на підставі української кваліфікації.',\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/', name: 'Троянда кохання', brand: 'psy', tag: 'Для пари · 15 хвилин',\n    text: 'Три ролі в парі: притягання, близькість і відповідальність. Дізнайся, які ролі звучать яскраво, а які стали тихішими, і як ви зустрічаєтеся одне з одним.' },\n  { id: 'kompas', path: 'kompas/', name: 'Компас адаптації', brand: 'coach', tag: 'Для себе · 10 хвилин',\n    text: 'Де ти зараз в еміграції: шість сфер нового життя, твій шлях між двома культурами і наступний маленький крок.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram-канал</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4><p>${p.text}</p><div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'Про авторку тесту'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono\">ІВ</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return BRAND === 'coach' ? 'Ірина Вознесенська · коуч ICF (Швейцарія) · психолог (Україна)' : 'Ірина Вознесенська · психолог (Україна) · коуч ICF (Швейцарія)';\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'Звідки ти про мене знаєш?', opts: ['Instagram','Telegram','Рекомендація друзів чи знайомих','Пошук у Google','Facebook','Інше'] },\n  interest: { q: 'Що тобі цікаво?', opts: ['Психологія: стосунки в парі','Коучинг: адаптація в еміграції та пошук себе','Поки що просто цікаво'] }\n};\nconst GREET = {\n  head: ['Привіт! Я {A}','Рада тобі! Мене звати {A}','Ласкаво просимо! Я {A}','Вітаю! Я {A}'],\n  about: ['Коуч ICF у Швейцарії та психолог в Україні.','Працюю у двох країнах: коуч ICF у Швейцарії та психолог в Україні.','Допомагаю людям знаходити себе й будувати теплі стосунки: як коуч ICF у Швейцарії і як психолог в Україні.'],\n  ask: ['Перед тестом дай, будь ласка, відповідь на два короткі питання. Так я краще зрозумію, чим можу бути тобі корисною.',\n        'Два короткі питання перед початком, і одразу переходимо до тесту.',\n        'Мені важливо знати, хто приходить на мої тести. Дай, будь ласка, відповідь на два короткі питання.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono\">ІВ</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} Можна позначити кілька варіантів.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Перейти до тестування</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, дякую за чесні відповіді.',\n           '{N}, ти вже робиш важливий крок: чесно дивишся на свою пару.',\n           '{N}, цей розбір — лише початок розмови.',\n           '{N}, тест показує картину, а справжні зміни починаються в розмові.',\n           '{N}, за кожною цифрою в цьому розборі стоїть твоя історія.'],\n    body: ['Цифри показують, де в парі стало тихо. Але за ними завжди є щось своє: втома, образи, звички, невисловлені очікування. На зустрічі ми дбайливо розберемо твою ситуацію і знайдемо перші кроки, щоб {F}.',\n           'Іноді досить одного точного питання, щоб пара знову почула одне одного. Якщо тобі хочеться {F}, запрошую на зустріч: спокійно, дбайливо, без оцінок.',\n           'Стосунки змінюються не від знань, а від нових дій. Я допомагаю парам знайти ці дії і не кинути їх за тиждень. Давай разом подивимося, як {F}.',\n           'До змін можна йти самотужки, а можна з підтримкою. На зустрічі ми обговоримо твій трикутник і окреслимо, як {F}.',\n           'Багато пар роками живуть з одним і тим самим напруженням, бо не знають, з чого почати розмову. Я допоможу почати її так, щоб {F}.'],\n    cta:  ['Запишися на зустріч-знайомство на 30 хвилин: обговоримо твій результат і вирішимо, чи потрібна подальша робота над стосунками.',\n           '30 хвилин онлайн. Ти розповідаєш, я слухаю і ставлю питання. Після зустрічі стане ясніше, що відбувається в парі і з чого почати.',\n           'Перша зустріч триває 30 хвилин. Цього досить, щоб зрозуміти твій запит і окреслити шлях роботи над стосунками.'],\n    title: ['Запрошую на зустріч на 30 хвилин','Давай поговоримо про твою пару','Наступний крок — розмова'],\n    legal: 'Консультації психолога проводяться онлайн для клієнтів в Україні.'\n  },\n  coach: {\n    open: ['{N}, дякую, що знаходиш час для себе.',\n           '{N}, ти вже робиш важливий крок: дивишся на себе чесно і дбайливо.',\n           '{N}, цей розбір — лише початок шляху.',\n           '{N}, іноді один тест відкриває більше питань, ніж відповідей. І це добре.',\n           '{N}, усе, що ти зараз бачиш, можна перетворити на опору.'],\n    body: ['Еміграція змінює все: мову, звички, ролі в родині і навіть те, як ми бачимо себе. У коучингу ми шукаємо твої опори в новому світі й крок за кроком допомагаємо тобі {F}.',\n           'Коли змінюється країна, змінюємося і ми. Іноді це відчувається як втрата себе. Я допомагаю знайти себе заново, щоб {F}.',\n           'За твоїми плечима вже великий шлях. Коучинг допомагає зібрати цей досвід у силу і {F}.',\n           'Відповіді вже є всередині тебе, але їх важко почути в метушні нового життя. У роботі зі мною ти знайдеш свої відповіді й вирішиш, як {F}.',\n           'Адаптація — це не лише документи й мова. Це пошук свого місця. Давай разом подивимося, як {F}.'],\n    cta:  ['Запишися на зустріч-знайомство на 30 хвилин: поговоримо про твій запит і про те, як може виглядати робота над собою.',\n           '30 хвилин онлайн. Ти розповідаєш про те, що для тебе зараз важливо, я ставлю питання. Після зустрічі стане ясніше, куди рухатися.',\n           'Перша зустріч триває 30 хвилин. Цього досить, щоб зрозуміти твій запит і окреслити перші кроки.'],\n    title: ['Запрошую на зустріч на 30 хвилин','Давай поговоримо про тебе','Наступний крок — розмова'],\n    legal: 'Коучинг не є психотерапією і не замінює психологічної чи медичної допомоги.'\n  }\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'принести у стосунки більше тепла й розуміння', coach: 'знайти своє місце в новому світі' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /^Коучинг/.test(x) : /^Психологі/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">Тобі цікавий і напрям «${AUTHOR[other].title.replace(/^./, c => c.toLowerCase())}». Про цю роботу можна дізнатися тут: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"eyebrow\">${key === 'psy' ? 'Робота над стосунками' : 'Робота над собою'}</div>\n    <h2>${pick(P.title, 0)}</h2>\n    <p class=\"lead\"><b>${fill(pick(P.open, 1))}</b></p>\n    <p>${fill(pick(P.body, 2))}</p>\n    <div class=\"invite-cta\"><p>${fill(pick(P.cta, 3))}</p>\n      <p><b>Як записатися:</b> напиши мені слово <b>«ЗУСТРІЧ»</b>, і я запропоную зручний час.</p>\n      <div class=\"invite-links\">${links.join('')}</div></div>\n    ${otherLine}\n    <p class=\"note\">${P.legal}</p></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Пройди також</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span>${t.text}</span><span class=\"tgo\">Пройти тест →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'Цей опитувальник — інструмент самопізнання і розмови. Він не є психологічною чи медичною діагностикою, психотерапевтичним висновком і не замінює консультації фахівця.',\n  'Результати відображають твоє особисте сприйняття за останні 4 тижні й можуть змінюватися.',\n  'Якщо ти переживаєш кризу, насильство чи загрозу своїй безпеці, звернися до фахівця або до екстрених служб своєї країни.'\n];\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Про цей опитувальник</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>Що дає проходження</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>Що з цим робити</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\nfunction disclaimerHtml(){\n  return `<div class=\"disclaimer\"><b>Важливо</b>${DISCLAIMER.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['Пройшла тест «Троянда кохання» для пари — цікаво і дуже точно. Пройди і ти, потім порівняємо:',\n                  'Знайшла тест «Троянда кохання»: 15 хвилин, і видно, які ролі в парі звучать яскраво, а які стали тихішими. Спробуй:'],\n  'kompas':      ['Пройшла тест «Компас адаптації» для тих, хто живе в еміграції. Дуже допомагає зрозуміти, де ти зараз. Спробуй:',\n                  'Знайшла тест «Компас адаптації»: 10 хвилин, і видно, що вже стало опорою в новій країні, а де поки тихо. Спробуй:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Спробуй цей тест:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Знаєш, кому цей тест теж може бути корисним? Перешли посилання.</p>`\n    : `<div class=\"eyebrow\">Поділитися</div><h3>Перешли тест друзям</h3><p>Якщо тест виявився корисним, надішли його тим, кому він теж може допомогти. ${TEST_META.id === 'roza-lyubvi' ? 'А ще краще — запропонуй пройти партнерові й порівняйте результати.' : 'Особливо тим, хто теж нещодавно переїхав.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Поділитися</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Скопіювати посилання</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Посилання на тест\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Посилання скопійовано. Встав його в повідомлення другові.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Скопіюй посилання з поля вище.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Познач, будь ласка, звідки ти про мене знаєш.' : !a.interest.length ? 'Познач, будь ласка, що тобі цікаво.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n", "/* ---------- схемы «Компаса адаптации» ----------\n   Простые линейные схемы на фоне страницы: тонкие линии, один акцентный цвет, без картинок. */\nconst LN = { ink:'#3A322B', muted:'#9A8D7E', line:'#D8CDBE', acc:'#8A5A3B', soft:'#EFE6D8' };\nconst sf = (x, y, t, o = {}) => `<text x=\"${x}\" y=\"${y}\" text-anchor=\"${o.a || 'middle'}\" font-family=\"${o.serif ? 'Forum, Georgia, serif' : 'Manrope, sans-serif'}\" font-size=\"${o.s || 12}\" font-weight=\"${o.w || 400}\" fill=\"${o.c || LN.ink}\" ${o.ls ? `letter-spacing=\"${o.ls}\"` : ''}>${t}</text>`;\n\n/* Обложка: тонкий компас */\nfunction compassSVG(){\n  const c = 70;\n  let s = `<svg viewBox=\"0 0 140 140\" role=\"img\" aria-label=\"Компас\" width=\"150\" height=\"150\">\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"60\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.2\"/>\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"52\" fill=\"none\" stroke=\"${LN.line}\" stroke-width=\"1\"/>`;\n  for (let k = 0; k < 24; k++){ const a = k * Math.PI / 12, r1 = k % 6 === 0 ? 44 : 49; s += `<line x1=\"${(c + r1 * Math.cos(a)).toFixed(1)}\" y1=\"${(c + r1 * Math.sin(a)).toFixed(1)}\" x2=\"${(c + 52 * Math.cos(a)).toFixed(1)}\" y2=\"${(c + 52 * Math.sin(a)).toFixed(1)}\" stroke=\"${LN.ink}\" stroke-width=\"${k % 6 === 0 ? 1.2 : .7}\"/>`; }\n  s += `<path d=\"M${c} ${c - 38} L${c + 7} ${c} L${c} ${c + 38} L${c - 7} ${c}Z\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.1\"/>\n    <path d=\"M${c} ${c - 38} L${c + 7} ${c} L${c - 7} ${c}Z\" fill=\"${LN.acc}\"/>\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"3\" fill=\"${LN.ink}\"/>` + sf(c, 20, 'Пн', { serif:true, s:12 });\n  return s + '</svg>';\n}\n\n/* Две культуры: схема 2 × 2 и точка — где человек сейчас */\nfunction shoresSVG(own, neu){\n  const W = 520, H = 420, x0 = 90, y0 = 30, S = 340;               // поле S×S\n  const px = x0 + S * neu / 20, py = y0 + S * (1 - own / 20);\n  const q = [['Свій острів', 0, 0], ['Міст між світами', 1, 0], ['Між двома берегами', 0, 1], ['Нове життя з чистого аркуша', 1, 1]];\n  const mine = (own >= 10 ? 0 : 1) * 2 + (neu >= 10 ? 1 : 0);\n  // цвета по спирали: своя культура — фиолетовый, мост — бирюзовый, между берегами — бежевый, новая культура — жёлтый\n  const QF = ['#EDEBF8', '#E1F5F6', '#F3F1EC', '#F9F5DE'], QL = ['#6A5FB8', '#2894A0', '#8E8470', '#A99A2E'];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Схема: своя і нова культура\">`;\n  q.forEach(([t, cx, cy], i) => {\n    const x = x0 + cx * S / 2, y = y0 + cy * S / 2;\n    s += `<rect x=\"${x}\" y=\"${y}\" width=\"${S / 2}\" height=\"${S / 2}\" fill=\"${QF[i]}\" opacity=\"${i === mine ? 1 : .35}\"/>`;\n    const words = t.split(' '), mid = Math.ceil(words.length / 2);\n    const l1 = words.length > 2 ? words.slice(0, mid).join(' ') : t, l2 = words.length > 2 ? words.slice(mid).join(' ') : '';\n    s += sf(x + S / 4, y + S / 4 - (l2 ? 4 : -4), l1, { serif:true, s:19, c: i === mine ? QL[i] : LN.muted });\n    if (l2) s += sf(x + S / 4, y + S / 4 + 20, l2, { serif:true, s:19, c: i === mine ? QL[i] : LN.muted });\n  });\n  s += `<rect x=\"${x0}\" y=\"${y0}\" width=\"${S}\" height=\"${S}\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1\"/>\n    <line x1=\"${x0 + S / 2}\" y1=\"${y0}\" x2=\"${x0 + S / 2}\" y2=\"${y0 + S}\" stroke=\"${LN.line}\" stroke-dasharray=\"3 4\"/>\n    <line x1=\"${x0}\" y1=\"${y0 + S / 2}\" x2=\"${x0 + S}\" y2=\"${y0 + S / 2}\" stroke=\"${LN.line}\" stroke-dasharray=\"3 4\"/>`;\n  [0, 10, 20].forEach(v => {\n    s += sf(x0 + S * v / 20, y0 + S + 18, v, { c:LN.muted, s:11 }) + sf(x0 - 10, y0 + S * (1 - v / 20) + 4, v, { a:'end', c:LN.muted, s:11 });\n  });\n  s += sf(x0 + S / 2, y0 + S + 42, 'зв’язок із новою культурою →', { c:LN.muted, s:12, ls:'.5' });\n  s += `<text transform=\"translate(${x0 - 40} ${y0 + S / 2}) rotate(-90)\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-size=\"12\" letter-spacing=\".5\" fill=\"${LN.muted}\">зв’язок зі своєю культурою →</text>`;\n  s += `<line x1=\"${px}\" y1=\"${y0 + S}\" x2=\"${px}\" y2=\"${py}\" stroke=\"${QL[mine]}\" stroke-dasharray=\"2 3\"/><line x1=\"${x0}\" y1=\"${py}\" x2=\"${px}\" y2=\"${py}\" stroke=\"${QL[mine]}\" stroke-dasharray=\"2 3\"/>\n    <circle cx=\"${px}\" cy=\"${py}\" r=\"9\" fill=\"${QL[mine]}\"/><circle cx=\"${px}\" cy=\"${py}\" r=\"15\" fill=\"none\" stroke=\"${QL[mine]}\" stroke-width=\"1\"/>`;\n  s += sf(px + (px > x0 + S - 60 ? -22 : 22), py - 16, 'ти тут', { a: px > x0 + S - 60 ? 'end' : 'start', c:QL[mine], w:700, s:15 });\n  return s + '</svg>';\n}\n\n/* Шесть сфер: дорожки 0–20, каждая сфера в своей рамке */\nfunction flowerSVG(sc){\n  const W = 560, rowH = 56, H = 30 + rowH * sc.length, x0 = 168, x1 = 486;\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Шість сфер\">`;\n  const max = Math.max(...sc), min = Math.min(...sc);\n  sc.forEach((v, k) => {\n    const y = 30 + k * rowH, x = x0 + (x1 - x0) * v / 20, hi = v === max || v === min;\n    const col = css(AC[k]), soft = css(AS[k]);\n    s += `<rect x=\"4\" y=\"${y - 22}\" width=\"${W - 8}\" height=\"44\" rx=\"10\" fill=\"${soft}\" stroke=\"${col}\" stroke-width=\"1.2\"/>`;\n    s += `<g transform=\"translate(20 ${y - 12})\">${aIcon(k).replace(/^<svg[^>]*>/, '').replace(/<\\/svg>$/, '')}</g>`;\n    s += sf(54, y + 6, AREAS[k].short, { a:'start', serif:true, s:19, c: col });\n    [5, 10, 15].forEach(t => { const tx = x0 + (x1 - x0) * t / 20; s += `<line x1=\"${tx}\" y1=\"${y - 7}\" x2=\"${tx}\" y2=\"${y + 7}\" stroke=\"${col}\" stroke-width=\".8\" opacity=\".35\"/>`; });\n    s += `<line x1=\"${x0}\" y1=\"${y}\" x2=\"${x1}\" y2=\"${y}\" stroke=\"#fff\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <line x1=\"${x0}\" y1=\"${y}\" x2=\"${x}\" y2=\"${y}\" stroke=\"${col}\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <circle cx=\"${x}\" cy=\"${y}\" r=\"${hi ? 9 : 7}\" fill=\"${col}\" stroke=\"#fff\" stroke-width=\"2\"/>`;\n    s += sf(x1 + 18, y + 6, `${v}/20`, { a:'start', s:14, w:700, c: col });\n  });\n  [0, 10, 20].forEach(v => { const x = x0 + (x1 - x0) * v / 20; s += sf(x, H - 2, v, { c:LN.muted, s:10 }); });\n  return s + '</svg>';\n}\n\n/* Путь адаптации: линия с этапами */\nfunction journeySVG(stage){\n  const W = 560, H = 190;\n  const P = [[50, 60], [200, 140], [360, 100], [510, 40]], names = ['Відкриття','Труднощі','Опори','Як удома'];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Шлях адаптації\">`;\n  s += `<path d=\"M50 60 C110 60 140 140 200 140 S310 100 360 100 S460 40 510 40\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.4\"/>`;\n  if (stage === 4) s += `<path d=\"M360 100 C390 150 300 175 280 140 C265 112 320 95 360 100\" fill=\"none\" stroke=\"${LN.acc}\" stroke-width=\"1.4\" stroke-dasharray=\"4 4\"/>`;\n  P.forEach(([x, y], i) => {\n    const on = i === stage;\n    s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"${on ? 9 : 6}\" fill=\"${on ? LN.acc : '#fff'}\" stroke=\"${on ? LN.acc : LN.ink}\" stroke-width=\"1.4\"/>`;\n    s += sf(x, y + (i === 1 ? 30 : 28), names[i], { serif:true, s:16, c: on ? LN.acc : LN.ink });\n  });\n  const at = stage === 4 ? [300, 165] : P[stage];\n  s += sf(at[0], at[1] - 18, stage === 4 ? 'новий виток · ти тут' : 'ти тут', { s:12, w:700, c:LN.acc, ls:'.4' });\n  return s + '</svg>';\n}\n", "/* =====================================================================\n   «Компас адаптации» — коучинговый самотест про адаптацию в эмиграции.\n   ===================================================================== */\nconst AREAS = [\n  { name: 'Мова і спілкування', short: 'Мова',\n    items: ['Я розмовляю місцевою мовою в повсякденних ситуаціях, навіть якщо з помилками.',\n            'Я вчу мову: заняття, застосунок, книжки, серіали.',\n            'Я сама чи сам починаю розмову з місцевими людьми, а не лише відповідаю на запитання.',\n            'Я читаю листи, сайти й оголошення місцевою мовою без перекладача або з мінімальною допомогою.',\n            'Я перепитую і прошу пояснити, якщо чогось не розумію, замість того щоб мовчати.'],\n    lv: ['Мова поки звучить тихо. Це нормально: мова — одне з найбільших навантажень в еміграції, і багатьом потрібен час, щоб почати говорити без страху. Кожна маленька розмова — це вже крок.',\n         'Мова в процесі: ти вже користуєшся нею, але, можливо, ще з напруженням або лише в знайомих ситуаціях. Зараз важлива регулярність, а не ідеальність.',\n         'Мова — твоя опора. Ти говориш, вчишся і не боїшся помилок. Це відчиняє двері до всього іншого: роботи, людей і відчуття, що ти тут не гість.'],\n    recs: ['Обери одну ситуацію на тиждень, де говориш лише місцевою мовою: кафе, магазин, сусіди.',\n           '15 хвилин мови щодня краще, ніж дві години раз на тиждень. Підійдуть серіал, подкаст або застосунок.',\n           'Знайди мовного партнера або розмовний клуб: там усі вчаться і помиляються разом.'],\n    focus: 'сміливіше заговорити новою мовою' },\n  { name: 'Побут і система', short: 'Побут',\n    items: ['Я спокійно даю раду документам, листам, страховці й рахункам.',\n            'Я знаю, куди звернутися, якщо щось сталося: лікар, адміністрація, страхова, юрист.',\n            'Я користуюся місцевими сервісами: транспорт, банк, пошта, застосунки.',\n            'Я розумію місцеві правила й неписані норми і дотримуюся їх без внутрішнього протесту.',\n            'Я роблю свій дім затишним: речі, порядок і дрібниці, які мені подобаються.'],\n    lv: ['Побут і система поки даються непросто. Листи, документи й правила нової країни можуть лякати і забирати багато сил. З цим стикаються майже всі, хто переїжджає.',\n         'У побуті ти вже орієнтуєшся, але деякі речі досі викликають тривогу або потребують багато сил. Ще трохи досвіду, і система стане зрозумілішою.',\n         'Побут і система — твоя опора. Ти знаєш, як усе влаштовано, і дієш упевнено. Це звільняє сили для того, що справді важливо.'],\n    recs: ['Заведи одну папку для всіх документів і листів і розбирай її раз на тиждень, в один і той самий час.',\n           'Склади список «куди дзвонити, якщо…»: лікар, страховка, адміністрація, екстрені служби.',\n           'Запитай у місцевих або досвідчених емігрантів про неписані правила. Багато що простіше, ніж здається.'],\n    focus: 'почуватися впевненіше в новій системі' },\n  { name: 'Справа і реалізація', short: 'Справа',\n    items: ['Я роблю кроки до роботи чи справи, які мені підходять: навчання, резюме, проєкти, співбесіди.',\n            'Я використовую свої навички й досвід, а не лише роблю те, що трапилося.',\n            'Я дізнаюся, як влаштований ринок праці і моя професія в новій країні.',\n            'Я доводжу розпочате до кінця і бачу результат своїх зусиль.',\n            'Я говорю про свої вміння й досягнення вголос, не применшуючи їх.'],\n    lv: ['Справа і реалізація зараз звучать тихо. Після переїзду багато хто тимчасово втрачає професійну опору, і це одна з найчутливіших тем. Важливо пам’ятати: твій досвід нікуди не зник.',\n         'Ти рухаєшся в бік своєї справи, але, можливо, поки не там, де хочеться, або використовуєш не все, що вмієш. Це проміжний етап, і з нього є вихід.',\n         'Справа і реалізація — твоя опора. Ти використовуєш свої сильні сторони й бачиш результат. Це дає впевненість і відчуття, що ти на своєму місці.'],\n    recs: ['Випиши 10 своїх умінь і досягнень, зокрема з минулого життя. Перечитуй перед важливими розмовами.',\n           'Поговори з двома людьми, які вже працюють у твоїй сфері в цій країні. Запитай, з чого вони починали.',\n           'Постав одну маленьку ціль на місяць: курс, резюме, проєкт або зустріч.'],\n    focus: 'знайти справу, в якій ти розкриєшся' },\n  { name: 'Люди і зв’язки', short: 'Люди',\n    items: ['Я зустрічаюся з друзями чи знайомими в новій країні наживо.',\n            'Я спілкуюся з місцевими людьми, а не лише з російськомовними.',\n            'Я підтримую зв’язок із близькими на батьківщині так, що мені від цього тепло, а не важко.',\n            'Я беру участь у чомусь разом з іншими: курси, клуби, волонтерство, спорт, батьківські чати.',\n            'Я ділюся своїми переживаннями хоча б з однією людиною й отримую підтримку.'],\n    lv: ['Зв’язки з людьми зараз звучать тихо. Самотність — частий супутник еміграції, навіть коли поруч родина. Нові зв’язки будуються повільно, і це нічого поганого про тебе не говорить.',\n         'Люди довкола тебе є, але, можливо, бракує глибини чи різноманіття: лише свої або лише по роботі. Тут легко зробити наступний крок.',\n         'Люди і зв’язки — твоя опора. Тобі є з ким розділити радість і труднощі, і в старому, і в новому житті. Це один із найсильніших захистів від стресу.'],\n    recs: ['Обери одне регулярне заняття з іншими людьми: спорт, хор, курс, волонтерство. Регулярність народжує дружбу.',\n           'Запроси когось на каву першою чи першим. Багато хто теж чекає, коли їх покличуть.',\n           'Домовся про постійний час для дзвінків близьким на батьківщині, щоб зв’язок був теплим, а не тривожним.'],\n    focus: 'знайти своїх людей у новій країні' },\n  { name: 'Ресурс: тіло і відпочинок', short: 'Ресурс',\n    items: ['Я висипаюся і прокидаюся з силами.',\n            'Я рухаюся: прогулянки, спорт, природа.',\n            'Я роблю щось лише для задоволення, без користі й мети.',\n            'Я помічаю, коли втомлююся, і даю собі відпочинок, а не «дотягую».',\n            'Я вибираюся в гарні місця нової країни й насолоджуюся ними.'],\n    lv: ['Ресурсу зараз мало. Адаптація забирає дуже багато енергії, і тіло часто першим подає сигнал утоми. Це не слабкість, а знак, що тобі потрібна турбота.',\n         'Ти дбаєш про себе, але не завжди. Коли стає важко, відпочинок і задоволення зникають першими. Варто зробити їх частиною розкладу.',\n         'Тіло і відпочинок — твоя опора. Ти вмієш відпочивати, рухатися і радіти. Це пальне для всіх інших сфер.'],\n    recs: ['Додай у кожен день одне маленьке задоволення без користі: кава на балконі, музика, прогулянка.',\n           'Рухайся хоча б 20 хвилин на день. Прогулянка теж рахується.',\n           'Раз на тиждень відкривай нове гарне місце в країні. Так нова країна потроху стає твоєю.'],\n    focus: 'повернути собі сили й радість' },\n  { name: 'Я і сенс', short: 'Сенс',\n    items: ['Я роблю те, що важливо особисто мені, а не лише те, що «треба».',\n            'Я уявляю, яким хочу бачити своє життя тут через рік, і роблю до цього кроки.',\n            'Я помічаю, що в мені виросло і змінилося завдяки переїзду.',\n            'Я ухвалюю рішення, спираючись на свої цінності, а не на чужі очікування.',\n            'Я дозволяю собі бути собою: говорю, вдягаюся, відпочиваю так, як мені до душі.'],\n    lv: ['Відчуття себе і сенсу зараз звучить тихо. Після переїзду багато хто відчуває, що втратив частину себе: колишні ролі, статус, звичні опори. Це час, коли можна заново зібрати себе.',\n         'Ти шукаєш себе в новому житті й уже знаходиш опори. Іноді повертається відчуття, що живеш не своїм життям. Це частина шляху.',\n         'Ти залишаєшся собою і живеш за своїми цінностями. Переїзд став не лише випробуванням, а й зростанням. Це найглибша опора адаптації.'],\n    recs: ['Щовечора записуй одну справу, яка сьогодні була важлива саме тобі.',\n           'Опиши, яким хочеш бачити своє життя тут через рік. Обери один крок до цього.',\n           'Згадай, що давало тобі сили до переїзду. Що з цього можна повернути тут?'],\n    focus: 'знайти себе і своє місце в новому світі' }\n];\nconst CULT = [\n  { name: 'Зв’язок зі своєю культурою',\n    items: ['Я розмовляю рідною мовою вдома або з друзями.',\n            'Я готую звичну їжу, відзначаю свята і традиції своєї культури.',\n            'Я читаю, дивлюся або слухаю щось рідною мовою.',\n            'Я спілкуюся з людьми зі своєї культури в новій країні.',\n            'Я передаю дітям чи близьким щось важливе зі своєї культури.'] },\n  { name: 'Зв’язок із новою культурою',\n    items: ['Я куштую місцеву їжу, пробую свята й звичаї.',\n            'Я дивлюся місцеві новини й фільми, слухаю місцеву музику.',\n            'Я ходжу на місцеві події: ярмарки, фестивалі, зібрання.',\n            'Я спілкуюся з місцевими людьми поза роботою.',\n            'Я дізнаюся історію та особливості країни, в якій живу.'] }\n];\nconst YEARS = ['менше 6 місяців','6–12 місяців','1–3 роки','3–5 років','понад 5 років'];\nconst STAGES = [\n  { phrase: 'Усе нове й цікаве, довкола багато відкриттів.', name: 'Час відкриттів',\n    text: 'Усе нове й надихає. Це чудовий час, щоб закласти опори: мову, знайомства, звички. З часом натхнення може змінитися втомою, і це нормальна частина шляху.' },\n  { phrase: 'Стало складніше: багато втоми, роздратування, хочеться додому.', name: 'Час труднощів',\n    text: 'Зараз може бути непросто: втома, роздратування, туга за домом. Це найчастіший і найприродніший етап адаптації. Він минає, особливо коли поруч є підтримка.' },\n  { phrase: 'Я поступово звикаю, знаходжу свої способи й опори.', name: 'Час опор',\n    text: 'Ти поступово знаходиш свої способи жити тут. Труднощі ще бувають, але опор стає більше. Зараз добре зміцнювати те, що вже працює.' },\n  { phrase: 'Тут мій дім, я можу бути собою.', name: 'Як удома',\n    text: 'Тут твій дім, і ти можеш бути собою. Це результат великого шляху. Тепер можна думати не лише про те, як упоратися, а й про те, чого тобі хочеться.' },\n  { phrase: 'Після спокійного періоду знову стало непросто.', name: 'Новий виток',\n    text: 'Після періоду стабільності знову стало непросто. Так буває: адаптація йде не по прямій, а хвилями. Нова хвиля — не відкат назад, а запрошення до наступного кроку.' }\n];\nconst STRATEGY = {\n  both: ['Міст між світами', 'Ти дбайливо зберігаєш свою культуру й водночас відкриваєшся новій. У психології адаптації це називають інтеграцією, і це найстійкіший шлях: у тебе є і коріння, і крила. Важливо й далі тримати обидва береги і не втомлюватися від подвійного навантаження.'],\n  newOnly: ['Нове життя з чистого аркуша', 'Ти активно входиш у нову культуру, а зв’язок зі своєю став тихішим. Це допомагає швидко освоїтися. Іноді разом із минулим іде й частина опори. Подумай, що зі своєї культури тобі хочеться зберегти для себе і близьких.'],\n  ownOnly: ['Свій острів', 'Ти бережеш свою культуру, мову і звички, а нова країна поки залишається трохи осторонь. Це дає безпеку і тепло. Наступний крок — потроху відкривати мости до нової культури, не втрачаючи свого.'],\n  none: ['Між двома берегами', 'Зараз зв’язок і зі своєю, і з новою культурою звучить тихо. Так часто буває в періоди втоми або одразу після переїзду, коли сил вистачає лише на головне. Це не назавжди. Навіть маленькі кроки до людей і традицій, своїх і нових, допомагають відчути опору.']\n};\nconst LV_NAME = ['поки звучить тихо','у процесі','твоя опора'];\nconst KEEP = 'Ця сфера вже працює на тебе. Зберігай те, що робиш, і спирайся на неї, коли стає важко.';\nconst LABELS = ['жодного разу','1–2 рази','іноді','часто','майже завжди'];\nconst AC = ['--a0','--a1','--a2','--a3','--a4','--a5'];\nconst AS = ['--a0s','--a1s','--a2s','--a3s','--a4s','--a5s'];\n\n/* ---------- состояние ---------- */\n// шаги: 0 — о переезде; 1–3 — по две сферы; 4 — две культуры\nlet step = 0, ctx = { years: null, stage: null }, ans = { areas: AREAS.map(() => Array(5).fill(null)), cult: CULT.map(() => Array(5).fill(null)) };\nlet myName = '', last = null;\nconst $ = id => document.getElementById(id);\nconst css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();\nconst sum = a => a.reduce((x, y) => x + y, 0);\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst lvl = s => s <= 7 ? 0 : s <= 13 ? 1 : 2;\nconst TOTAL = 5 * 6 + 10 + 2;\n\n$('startBtn').addEventListener('click', () => {\n  myName = $('nameMe').value.trim();\n  resetInvite(); window.__leadCountry = '';\n  step = 0; ctx = { years: null, stage: null };\n  ans = { areas: AREAS.map(() => Array(5).fill(null)), cult: CULT.map(() => Array(5).fill(null)) };\n  $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0);\n});\n\nfunction choiceGroup(title, opts, key){\n  const wrap = document.createElement('div'); wrap.className = 'q';\n  wrap.innerHTML = `<p>${title}</p><div class=\"choices1\" role=\"group\"></div>`;\n  const g = wrap.querySelector('.choices1');\n  opts.forEach((o, i) => {\n    const b = document.createElement('button'); b.className = 'opt1'; b.id = `c-${key}-${i}`; b.textContent = o;\n    b.setAttribute('aria-pressed', ctx[key] === i ? 'true' : 'false');\n    b.addEventListener('click', () => { ctx[key] = i; g.querySelectorAll('.opt1').forEach((x, n) => x.setAttribute('aria-pressed', n === i ? 'true' : 'false')); update(); });\n    g.appendChild(b);\n  });\n  return wrap;\n}\nfunction scaleItem(text, num, arr, i, idPrefix){\n  const q = document.createElement('div'); q.className = 'q';\n  q.innerHTML = `<p><span class=\"n\">${num}.</span>${text}</p><div class=\"opts\" role=\"group\" aria-label=\"Оцінка\"></div>`;\n  const opts = q.querySelector('.opts');\n  for (let v = 0; v <= 4; v++){\n    const o = document.createElement('button'); o.className = 'opt'; o.id = `${idPrefix}-${i}-${v}`;\n    o.setAttribute('aria-pressed', arr[i] === v ? 'true' : 'false');\n    o.innerHTML = `<b>${v}</b><small>${LABELS[v]}</small>`;\n    o.addEventListener('click', () => { arr[i] = v; opts.querySelectorAll('.opt').forEach((x, n) => x.setAttribute('aria-pressed', n === v ? 'true' : 'false')); update(); });\n    opts.appendChild(o);\n  }\n  return q;\n}\nfunction renderStep(){\n  const list = $('qlist'); list.innerHTML = '';\n  $('stepLabel').textContent = `Крок ${step + 1} з 5`;\n  if (step === 0){\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'Про твій переїзд';\n    $('roleTitle').textContent = 'Де ти зараз'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'Два короткі питання, щоб розбір був точнішим.';\n    list.appendChild(choiceGroup('Скільки ти живеш у новій країні?', YEARS, 'years'));\n    list.appendChild(choiceGroup('Яка фраза зараз найближча?', STAGES.map(s => s.phrase), 'stage'));\n  } else if (step <= 3){\n    const pair = [(step - 1) * 2, (step - 1) * 2 + 1];\n    document.documentElement.style.setProperty('--accent', `var(${AC[pair[0]]})`);\n    $('partTag').textContent = 'Сфери нового життя · за останні 4 тижні';\n    $('roleTitle').textContent = `${AREAS[pair[0]].name} · ${AREAS[pair[1]].name}`; $('roleTitle').style.color = `var(${AC[pair[0]]})`;\n    $('roleSub').textContent = 'Відзначай, як часто це було насправді.';\n    let n = (step - 1) * 10;\n    pair.forEach(a => {\n      const h = document.createElement('div'); h.className = 'qhead'; h.style.color = `var(${AC[a]})`; h.textContent = AREAS[a].name; list.appendChild(h);\n      AREAS[a].items.forEach((t, i) => list.appendChild(scaleItem(t, ++n, ans.areas[a], i, `a${a}`)));\n    });\n  } else {\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'Дві культури · за останні 4 тижні';\n    $('roleTitle').textContent = 'Твоя культура і нова'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'Тут немає правильного балансу. Важливо просто побачити, як це в тебе зараз.';\n    let n = 30;\n    CULT.forEach((c, k) => {\n      const h = document.createElement('div'); h.className = 'qhead'; h.textContent = c.name; list.appendChild(h);\n      c.items.forEach((t, i) => list.appendChild(scaleItem(t, ++n, ans.cult[k], i, `c${k}`)));\n    });\n  }\n  $('next').textContent = step === 4 ? 'Показати розбір' : 'Далі';\n  update();\n}\nfunction doneCount(){\n  return (ctx.years !== null) + (ctx.stage !== null) + ans.areas.flat().filter(v => v !== null).length + ans.cult.flat().filter(v => v !== null).length;\n}\nfunction stepComplete(){\n  if (step === 0) return ctx.years !== null && ctx.stage !== null;\n  if (step <= 3) return [(step - 1) * 2, (step - 1) * 2 + 1].every(a => ans.areas[a].every(v => v !== null));\n  return ans.cult.every(c => c.every(v => v !== null));\n}\nfunction update(){\n  const d = doneCount();\n  $('countLabel').textContent = `${d} з ${TOTAL}`;\n  $('prog').style.width = (d / TOTAL * 100) + '%';\n  $('next').disabled = !stepComplete();\n}\n$('next').addEventListener('click', () => { if (step < 4){ step++; renderStep(); window.scrollTo(0, 0); } else showResult(); });\n$('back').addEventListener('click', () => {\n  if (step > 0){ step--; renderStep(); window.scrollTo(0, 0); }\n  else { $('quiz').hidden = true; $('intro').hidden = false; }\n});\n\n/* ---------- картинки ---------- */\nfunction aIcon(k){\n  const c = css(AC[k]);\n  const p = [\n    `<path d=\"M4 5h16v10H9l-5 4z\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/>`,\n    `<path d=\"M3 11.2 12 3.5l9 7.7V21h-6.2v-5.6H9.2V21H3z\" fill=\"${c}\"/>`,\n    `<path d=\"M12 3l2.6 5.6 6 .7-4.5 4.1 1.2 6L12 16.4 6.7 19.4l1.2-6L3.4 9.3l6-.7z\" fill=\"${c}\"/>`,\n    `<circle cx=\"8\" cy=\"9\" r=\"3.4\" fill=\"${c}\"/><circle cx=\"16\" cy=\"9\" r=\"3.4\" fill=\"${c}\"/><path d=\"M2.5 20c.6-3.6 3-5.5 5.5-5.5s4.9 1.9 5.5 5.5M10.5 20c.6-3.6 3-5.5 5.5-5.5s4.9 1.9 5.5 5.5\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2\"/>`,\n    `<path d=\"M12 21s-7.5-4.6-7.5-10.2A4.3 4.3 0 0 1 12 8a4.3 4.3 0 0 1 7.5 2.8C19.5 16.4 12 21 12 21z\" fill=\"${c}\"/>`,\n    `<circle cx=\"12\" cy=\"12\" r=\"8.5\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2.2\"/><circle cx=\"12\" cy=\"12\" r=\"3\" fill=\"${c}\"/>`][k];\n  return `<svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" aria-hidden=\"true\">${p}</svg>`;\n}\nconst bar = (v, max, color) => `<div class=\"bar\"><i style=\"width:${v / max * 100}%;background:${color}\"></i></div>`;\n\n/* ---------- разбор ---------- */\nfunction compute(){\n  const sc = ans.areas.map(sum);\n  const own = sum(ans.cult[0]), neu = sum(ans.cult[1]);\n  const key = own >= 10 && neu >= 10 ? 'both' : neu >= 10 ? 'newOnly' : own >= 10 ? 'ownOnly' : 'none';\n  const idx = Math.round(sum(sc) / 120 * 100);\n  const strong = sc.indexOf(Math.max(...sc)), weak = sc.lastIndexOf(Math.min(...sc));\n  return { sc, own, neu, key, idx, strong, weak };\n}\nfunction buildBlocks(){\n  const r = compute(); last = r;\n  const N = esc(myName);\n  const [sName, sText] = STRATEGY[r.key];\n  const st = STAGES[ctx.stage];\n  const date = new Date().toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long', year: 'numeric' });\n  const B = [];\n\n  B.push({ html: `<div class=\"blk hero k-hero\"><div class=\"split\">\n      <div class=\"stack\" style=\"gap:10px\"><div class=\"eyebrow\">Компас адаптації · розбір</div>\n        ${N ? `<div class=\"names\">${N}</div>` : ''}\n        <h1>${sName}</h1>\n        <p class=\"note\">${date} · у країні ${YEARS[ctx.years]} · етап: ${st.name.toLowerCase()}</p></div>\n      <div class=\"fig\" style=\"flex:0 0 150px;width:150px\">${compassSVG()}</div></div></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Дві культури</div><h2>Твій шлях між двома культурами</h2>\n      <div style=\"max-width:460px;width:100%;margin:0 auto\">${shoresSVG(r.own, r.neu)}</div>\n      <h3>${sName}</h3><p>${sText}</p>\n      <p class=\"note\">Своя культура: <b>${r.own} з 20</b> · нова культура: <b>${r.neu} з 20</b>. Зв’язок вважається сильним від 10 балів.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Етап адаптації</div><h2>${st.name}</h2>${journeySVG(ctx.stage)}<p>${st.text}</p>\n      <p class=\"note\">Етапи описано за класичною моделлю адаптації до нової культури (U-крива). У кожної людини свій темп, і етапи можуть повторюватися.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Шість сфер</div><h2>Шість сфер твого нового життя</h2>${flowerSVG(r.sc)}\n      <p class=\"note\">Кожна сфера — від 0 до 20 балів. Загальний індекс адаптації: <b>${r.idx}%</b>. Це не оцінка, а точка відліку.</p></div>` });\n  B.push({ html: testInfoHtml() });\n\n  B.push({ newPage: true, html: `<div class=\"blk plain\"><div class=\"eyebrow\">Докладно за сферами</div><h2>Де твої опори і де поки тихо</h2>\n      <p>Найсильніша сфера зараз — <b style=\"color:var(${AC[r.strong]})\">${AREAS[r.strong].name.toLowerCase()}</b>. На неї можна спиратися. Найтихіша — <b style=\"color:var(${AC[r.weak]})\">${AREAS[r.weak].name.toLowerCase()}</b>. З неї зручно почати.</p></div>` });\n  r.sc.forEach((s, k) => {\n    const l = lvl(s);\n    const recs = l === 2 ? `<p class=\"recs\" style=\"padding-left:14px\">${KEEP}</p>`\n      : `<div class=\"recs-t\">Що допоможе</div><ul class=\"recs\">${AREAS[k].recs.map(x => `<li>${x}</li>`).join('')}</ul>`;\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:var(${AC[k]});--cs:var(${AS[k]})\">\n      <div class=\"role-head\"><div class=\"ico\">${aIcon(k)}</div><h3>${AREAS[k].name}</h3>\n        <span class=\"pill\" style=\"background:var(${AC[k]})\">${LV_NAME[l]}</span><span class=\"sc\">${s} / 20</span></div>\n      <p>${AREAS[k].lv[l]}</p>${recs}</div>` });\n  });\n\n  const low = AREAS[r.weak].items.map((t, i) => [t, ans.areas[r.weak][i]]).sort((a, b) => a[1] - b[1]).slice(0, 2);\n  const ritual = ['Раз на тиждень роби щось уперше в новій країні: місце, страва, подія.',\n                  'Раз на тиждень відпочивай по-справжньому: без справ, без телефона, з тим, що тебе наповнює.',\n                  'Раз на тиждень відзначай, що вже вдалося. Маленькі перемоги теж рахуються.',\n                  'Раз на місяць думай про те, чого тобі хочеться тут далі, і обирай один крок.',\n                  'Раз на тиждень роби щось дбайливе для себе й поговори з тим, хто тебе підтримує.'][ctx.stage];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">План на 4 тижні</div><h2>Маленькі кроки, які змінюють життя</h2>\n    <div class=\"steps\">\n      <div><span class=\"num\">1</span><div><b>Твоя сфера зростання: ${AREAS[r.weak].name.toLowerCase()}</b><p>Обери одну дію й роби її хоча б двічі на тиждень:</p>\n        <ul class=\"clean\" style=\"margin-top:6px\">${low.map(([t]) => `<li>${t.replace(/^Я (сама чи сам )?/, '').replace(/^./, c => c.toUpperCase())}</li>`).join('')}</ul></div></div>\n      <div><span class=\"num\">2</span><div><b>Твоя опора: ${AREAS[r.strong].name.toLowerCase()}</b><p>Коли стає важко, спирайся на цю сферу. Помічай, що в ній у тебе виходить, і дозволь їй підтримувати решту.</p></div></div>\n      <div><span class=\"num\">3</span><div><b>Ритуал етапу «${st.name.toLowerCase()}»</b><p>${ritual}</p></div></div>\n      <div><span class=\"num\">4</span><div><b>Через 4 тижні</b><p>Пройди тест ще раз і подивися, як змінився твій компас.</p></div></div>\n    </div></div>` });\n  B.push({ html: `<div class=\"blk\"><h2>Питання для роздумів</h2><p class=\"note\">Не поспішай із відповідями. Можна записати їх або просто побути з ними.</p>\n    <ul class=\"clean\">\n      <li>Коли ти на своєму місці, ти як що? На що це схоже?</li>\n      <li>Що тобі вже допомагає в новій країні? Що ще могло б допомогти?</li>\n      <li>Чого тобі хочеться для себе в цій країні?</li>\n      <li>Що з колишнього життя ти хочеш зберегти, а що можна дбайливо відпустити?</li>\n      <li>Хто або що підтримує тебе тут?</li>\n      <li>Який маленький крок цього тижня наблизить тебе до відчуття «я вдома»?</li>\n    </ul></div>` });\n\n  B.push({ html: inviteHtml({ name: myName, country: window.__leadCountry || '', interest: surveyAnswers().interest,\n                              focus: { coach: AREAS[r.weak].focus, psy: 'принести у стосунки більше тепла й розуміння' } }) });\n  B.push({ html: moreTestsHtml(TEST_META.id) });\n  B.push({ html: authorHtml() });\n  B.push({ html: disclaimerHtml() });\n  r.sName = sName;\n  return B;\n}\nfunction showResult(){\n  $('report').innerHTML = buildBlocks().map(b => b.html).join('');\n  $('quiz').hidden = true; $('result').hidden = false; window.scrollTo(0, 0);\n}\n\n/* ---------- связь с общей анкетой ---------- */\nconst LEAD_HOOKS = {\n  personName: () => myName,\n  fileBase: () => 'Kompas_adaptatsii',\n  fileNames: () => myName ? [myName] : [],\n  payload: () => {\n    const r = last, scores = {};\n    AREAS.forEach((a, k) => scores[a.name] = r.sc[k]);\n    scores['Своя культура'] = r.own; scores['Новая культура'] = r.neu; scores['Индекс адаптации, %'] = r.idx;\n    return { result: r.sName, scores, notes: `в стране: ${YEARS[ctx.years]}; этап: ${STAGES[ctx.stage].name}; опора: ${AREAS[r.strong].name}; рост: ${AREAS[r.weak].name}` };\n  }\n};\n\n/* значки на плитках сфер на стартовой странице */\ndocument.querySelectorAll('.k-roles .role').forEach((el, k) => {\n  const b = el.querySelector('b'); if (!b) return;\n  const w = document.createElement('div'); w.className = 'ri';\n  w.innerHTML = aIcon(k); b.parentNode.insertBefore(w, b); w.appendChild(b);\n});\n", "/* =====================================================================\n   Общая анкета перед PDF, отправка в Google Таблицу и сборка PDF.\n   Тест задаёт: TEST_META {id, name}, buildBlocks(), showResult(), LEAD_HOOKS.\n   ===================================================================== */\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nfunction leadFormHtml(){\n  return `<div class=\"blk actions\" style=\"margin-top:18px\">\n    <h3>Отримати розбір у PDF</h3>\n    <p>Гарний PDF із розбором без питань тесту: ілюстрації, описи, рекомендації, план на 4 тижні та питання для роздумів. Залиш контакти, і файл одразу завантажиться.</p>\n    <form id=\"lead\" class=\"stack\" style=\"gap:12px\" novalidate>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fName\">Ім’я *</label><input id=\"fName\" maxlength=\"40\" required autocomplete=\"given-name\"></div>\n        <div class=\"field\"><label for=\"fEmail\">E-mail *</label><input id=\"fEmail\" type=\"email\" maxlength=\"80\" required autocomplete=\"email\"></div>\n      </div>\n      <div class=\"field\"><label for=\"fContact\">Telegram або WhatsApp</label><input id=\"fContact\" maxlength=\"60\" placeholder=\"@username або +41 …\"></div>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fCountry\">Країна *</label><select id=\"fCountry\" required><option value=\"\">Обери країну</option></select></div>\n        <div class=\"field\"><label for=\"fCity\">Місто</label><input id=\"fCity\" maxlength=\"40\" autocomplete=\"address-level2\"></div>\n      </div>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fConsent\" required> <span>Я погоджуюся на обробку моїх даних для надсилання результатів і зв’язку зі мною *</span></label>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fNews\"> <span>Хочу отримувати корисні матеріали про стосунки, адаптацію та життя в еміграції</span></label>\n      <p class=\"err\" id=\"formErr\" hidden></p>\n      <div class=\"row\">\n        <button class=\"btn\" type=\"submit\" id=\"pdfBtn\">Отримати PDF</button>\n        <button class=\"btn ghost\" type=\"button\" id=\"again\">Пройти знову</button>\n      </div>\n      <p class=\"note\">Твої дані бачить лише Ірина Вознесенська. Вони не передаються третім особам.</p>\n    </form>\n    <span class=\"status\" id=\"status\" hidden></span>\n  </div>`;\n}\ndocument.querySelectorAll('[data-lead]').forEach(el => el.innerHTML = leadFormHtml());\n(function fillCountries(){\n  const sel = document.getElementById('fCountry'); if (!sel) return;\n  const g1 = document.createElement('optgroup'); g1.label = 'Часто обирають';\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = 'Усі країни';\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option('Інша країна', OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n})();\n\nconst el = id => document.getElementById(id);\nfunction setStatus(t){ el('status').textContent = t; el('status').hidden = !t; }\nfunction setErr(t){ el('formErr').textContent = t; el('formErr').hidden = !t; }\nel('again').addEventListener('click', () => { el('result').hidden = true; el('intro').hidden = false; window.scrollTo(0,0); });\n\nconst LS = 'irinaTestsLead';\nfunction loadLead(){ try { return JSON.parse(localStorage.getItem(LS) || 'null'); } catch(e){ return null; } }\nfunction saveLead(v){ try { localStorage.setItem(LS, JSON.stringify(v)); } catch(e){} }\n\nconst _showResult = showResult;\nshowResult = function(){\n  _showResult();\n  const saved = loadLead();\n  el('fName').value = saved?.name || LEAD_HOOKS.personName() || '';\n  if (saved){\n    el('fEmail').value = saved.email || ''; el('fContact').value = saved.contact || '';\n    el('fCountry').value = (COUNTRIES.includes(saved.country) || saved.country === OTHER_COUNTRY) ? saved.country : '';\n    el('fCity').value = saved.city || '';\n  }\n  setErr(''); setStatus('');\n};\n\n// Чёткость PDF: 3 = около 290 точек на дюйм (хорошо для печати). На слабых телефонах — 2.5.\nconst PDF_SCALE = (/iPhone|iPad|Android/i.test(navigator.userAgent) && (navigator.deviceMemory || 4) < 4) ? 2.5 : 3;\nasync function buildPdf(){\n  const stage = el('stage'); stage.innerHTML = '';\n  const blocks = buildBlocks();\n  const pages = [];\n  const newPage = () => {\n    const p = document.createElement('div'); p.className = 'pdf-page';\n    p.innerHTML = `<div class=\"strip\"></div><div class=\"pbody\"></div><div class=\"pfoot\"><span>${footerLine()}</span><span class=\"pn\"></span></div>`;\n    stage.appendChild(p); pages.push(p); return p.querySelector('.pbody');\n  };\n  let body = newPage();\n  for (const b of blocks){\n    if (!b.html) continue;\n    if (b.newPage && body.children.length) body = newPage();\n    const holder = document.createElement('div'); holder.innerHTML = b.html; const node = holder.firstElementChild;\n    body.appendChild(node);\n    if (body.scrollHeight > body.clientHeight + 1 && body.children.length > 1){ node.remove(); body = newPage(); body.appendChild(node); }\n  }\n  pages.forEach((p, i) => p.querySelector('.pn').textContent = `${i+1} / ${pages.length}`);\n  if (document.fonts && document.fonts.ready) await document.fonts.ready;\n  const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({ unit:'pt', format:'a4', compress:true });\n  const bg = getComputedStyle(document.documentElement).getPropertyValue('--pdf-bg').trim() || '#FFFFFF';\n  for (let i = 0; i < pages.length; i++){\n    const canvas = await html2canvas(pages[i], { scale:PDF_SCALE, backgroundColor:'#FFFFFF', useCORS:true, logging:false });\n    if (i) pdf.addPage();\n    pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, 595.28, 841.89, undefined, 'FAST');\n    const pr = pages[i].getBoundingClientRect(), k = 595.28 / pr.width;\n    pages[i].querySelectorAll('a[href]').forEach(a => {\n      if (!/^https?:/.test(a.href)) return;\n      const r = a.getBoundingClientRect();\n      pdf.link((r.left - pr.left) * k, (r.top - pr.top) * k, r.width * k, r.height * k, { url: a.href });\n    });\n  }\n  stage.innerHTML = '';\n  return pdf.output('blob');\n}\n\nfunction translit(t){\n  const m = {а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'e',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'sch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya',і:'i',ї:'yi',є:'ye',ґ:'g'};\n  return String(t).toLowerCase().split('').map(c => m[c] ?? c).join('').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');\n}\nlet downloadsCap = null;\n(async () => { try { if (window.claude && window.claude.use) downloadsCap = await window.claude.use('downloads'); } catch(e){ downloadsCap = null; } })();\nasync function saveBlob(blob, filename){\n  if (downloadsCap){ await downloadsCap.save({ filename, data: blob }); return; }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = filename; a.rel = 'noopener'; document.body.appendChild(a); a.click(); setTimeout(() => a.remove(), 1000);\n  setTimeout(() => URL.revokeObjectURL(url), 60000);\n}\n\nasync function sendLead(lead){\n  if (!ENDPOINT) return;\n  const src = new URLSearchParams(location.search);\n  const sv = surveyAnswers();\n  const t = LEAD_HOOKS.payload();\n  const payload = {\n    ...lead,\n    testId: TEST_META.id, testName: TEST_META.name, lang: PAGE_LANG,\n    heard: sv.heard.join(', '), interest: sv.interest.join(', '),\n    result: t.result, scores: t.scores, notes: t.notes || '',\n    source: src.get('utm_source') || src.get('src') || document.referrer || 'прямой заход'\n  };\n  try {\n    await fetch(ENDPOINT, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body: JSON.stringify(payload) });\n  } catch(e){ /* PDF всё равно выдаётся */ }\n}\n\nel('lead').addEventListener('submit', async (ev) => {\n  ev.preventDefault(); setErr('');\n  const lead = {\n    name: el('fName').value.trim(), email: el('fEmail').value.trim(), contact: el('fContact').value.trim(),\n    country: el('fCountry').value.trim(), city: el('fCity').value.trim(), marketing: el('fNews').checked\n  };\n  if (!lead.name) return setErr('Напиши, будь ласка, своє ім’я.');\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(lead.email)) return setErr('Перевір e-mail: схоже, у ньому помилка.');\n  if (!lead.country) return setErr('Обери, будь ласка, країну зі списку.');\n  if (!el('fConsent').checked) return setErr('Щоб отримати PDF, потрібна згода на обробку даних.');\n  if (!window.jspdf || !window.html2canvas) return setErr('Не вдалося завантажити модуль PDF. Перевір інтернет і онови сторінку.');\n  const btn = el('pdfBtn'); btn.disabled = true; setStatus('Готую PDF…');\n  try {\n    saveLead(lead);\n    window.__leadCountry = lead.country;\n    await sendLead(lead);\n    const blob = await buildPdf();\n    await saveBlob(blob, [LEAD_HOOKS.fileBase(), ...LEAD_HOOKS.fileNames().map(translit)].filter(Boolean).join('_') + '.pdf');\n    setStatus('Готово! PDF збережено. Якщо він не відкрився, зазирни в папку «Завантаження».');\n  } catch(e){\n    setStatus('');\n    setErr(e && e.code === 'declined' ? 'Збереження скасовано.' : 'Не вдалося підготувати PDF. Спробуй ще раз.');\n  } finally { btn.disabled = false; }\n});\nwindow.__buildPdf = buildPdf;\n"]};
